function hsv(h,s,v){ h=((h%360)+360)%360; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b;
  if(h<60){r=c;g=x;b=0;}else if(h<120){r=x;g=c;b=0;}else if(h<180){r=0;g=c;b=x;}
  else if(h<240){r=0;g=x;b=c;}else if(h<300){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [r+m,g+m,b+m]; }

// ---- coarse per-pixel Lyapunov buffer, upscaled ----
const BW = Math.max(240, Math.min(280, Math.round(width / 4.6))), BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

const AB = ['AABAB','BBABA','AB','ABBA','AAB','ABB','AABBB','BBBBBBAAAAAA','AABABB','ABABBA'];
// ---- seed-dependent framing (rebuild on seed change) ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
  S.ca0 = (fr(1)-0.5)*0.5;    // center offset a
  S.cb0 = (fr(2)-0.5)*0.5;    // center offset b
  S.ph  = fr(3)*6.2831;       // pan phase
  S.hoff = (fr(4)-0.5)*40;    // hue jitter
  S.abBase = Math.floor(fr(5)*AB.length);
  S.secUsed = -1;             // force AB-string rebuild
}
// ---- section-morph the AB-string (dramaturgy) ----
const sec = K.section|0;
if (S.secUsed !== sec) {
  S.secUsed = sec;
  const str = AB[(S.abBase + sec) % AB.length];
  const seq = new Array(str.length);
  for (let i=0;i<str.length;i++) seq[i] = str[i]==='B'?1:0;
  S.seq = seq; S.L = seq.length;
}
const seq = S.seq, L = S.L;

// ---- animated params (read every frame) ----
const style = P.style;
const t = K.t * (0.05 + P.speed*0.08);
const hb = P.hue + S.hoff + Math.sin(sec*0.5 + K.t*0.02)*10;
const hueShift = hb - 168;
const expo = 0.36 + P.energy*0.9 + K.intensity*0.28 + A.rms*0.5 + K.pulse*0.06;
const dens = P.density;
const warm = 20, N = Math.floor(34 + P.detail*56 + K.intensity*10);

// ---- pan/zoom the (a,b) window on K.t (motion floor) ----
const rMin = 2.55, rMax = 3.999, mid = (rMin+rMax)/2;
let half = 0.62 / (0.45 + P.scale*0.95);
half *= (1 + 0.12*Math.sin(t*0.17) + A.rms*0.2);
half = Math.min(half, (rMax-rMin)*0.5 - 0.002);
const cMin = rMin+half, cMax = rMax-half;
const amp = Math.max(0, (cMax-cMin)*0.34);
let ca = mid + S.ca0*0.6 + amp*Math.sin(t*0.31 + S.ph) + (P.x-0.5)*0.5;
let cb = mid + S.cb0*0.6 + amp*Math.cos(t*0.23 + S.ph*1.3) + (P.y-0.5)*0.5;
ca = clamp(ca, cMin, cMax); cb = clamp(cb, cMin, cMax);
const aMin = ca-half, bMin = cb-half, da = 2*half, db = 2*half;

const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j=0;j<BH;j++){
  const bR = bMin + (j/(BH-1))*db;        // growth rate b for this row
  for (let i=0;i<BW;i++){
    const aR = aMin + (i/(BW-1))*da;       // growth rate a for this column
    let x = 0.5, kk = 0;
    for (let w=0; w<warm; w++, kk++){ const r = seq[kk%L]?bR:aR; x = r*x*(1-x); }
