        cr=c0[0]; cg=c0[1]; cb2=c0[2];
      } else if (style==='etched'){
        const lines = s*(3 + dens*7);
        const f = lines - Math.floor(lines);
        const edge = Math.min(f, 1-f);
        const ink = clamp((0.16-edge)/0.10, 0, 1);
        const v = clamp((0.10 + s2*0.9)*expo, 0, 1);
        const gr = clamp(v*(1 - 0.4*ink) + 0.04, 0, 1);
        cr=gr; cg=gr; cb2=gr*1.02;
      } else { // zircon (teal -> gold ridges)
        const c0 = hsv(180 - s2*132 + hueShift, clamp(0.5 + s2*0.42,0,1), clamp((0.18 + s2*0.74)*expo,0,1));
        cr=c0[0]; cg=c0[1]; cb2=c0[2];
      }
    } else {
      const c = clamp(lyap/0.7, 0, 1);        // chaotic amount
      if (style==='copper'){ const v=clamp((0.03+c*0.05)*expo,0,0.22); const c0=hsv(18,0.7,v); cr=c0[0];cg=c0[1];cb2=c0[2]; }
      else if (style==='thermal'){ const v=clamp(c*0.05,0,0.1); cr=v; cg=v*0.2; cb2=v*0.45; }
      else if (style==='bio-membrane'){ const c0=hsv(288+hueShift*0.3,0.75,clamp((0.05+c*0.10)*expo,0,0.3)); cr=c0[0];cg=c0[1];cb2=c0[2]; }
      else if (style==='etched'){ const v=clamp(0.02+c*0.02,0,0.07); cr=v;cg=v;cb2=v; }
      else { const c0=hsv(196+hueShift,0.62,clamp((0.035+c*0.08)*expo,0,0.24)); cr=c0[0];cg=c0[1];cb2=c0[2]; }
    }
    const o = 4*(j*BW+i);
    px[o]=clamp(cr*255,0,255); px[o+1]=clamp(cg*255,0,255); px[o+2]=clamp(cb2*255,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();
// audio-reactive bloom (partial ADD wash — never full-frame flash, won't strobe)
if ((A.bass>0.02 || A.rms>0.02) && style!=='etched'){
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass*0.5 + A.rms*0.4)*P.energy;
  fill((hb+20)%360, 45, 100, clamp(glow*18,0,20));
  rect(0,0,width,height);
  blendMode(BLEND); pop();
}
